#!/usr/bin/env bash
set -euo pipefail

# ============================================================================
# Fase 8e -- Causa real de "falta la clave API": el despliegue en producción
# no es docker-compose.prod.yml sino Cloud Run vía GitHub Actions
# (.github/workflows/deploy-cloud-run.yml, se dispara en cada push a main).
#
# Ese workflow despliega el backend con `gcloud run deploy --env-vars-file=...`,
# y ESE MODO REEMPLAZA TODAS las variables de entorno del servicio en cada
# despliegue -- el YAML que genera solo traía NODE_ENV, JWT_EXPIRES_IN,
# DATABASE_URL y JWT_SECRET. Por eso, aunque se pusiera ORS_API_KEY a mano en
# la consola de Cloud Run, el siguiente push a main (cualquier push, incluidos
# los de las fases anteriores) la borraba sin más -- de ahí que el mensaje
# "falta la clave API" persistiera pese a los cambios previos.
#
# Este script añade ORS_API_KEY a ese fichero YAML generado en el workflow,
# tomándola de un nuevo secreto de GitHub llamado ORSAPIKEY (mismo criterio
# de nombres sin guion bajo que ya usan GCPPROJECTID/GCPSAKEY/DATABASEURL/
# JWTSECRET/VITEGOOGLEMAPSAPIKEY).
#
# PASO MANUAL IMPRESCINDIBLE tras aplicar este script (esto no lo puede hacer
# ningún script, es una acción en la web de GitHub):
#   1. Ve a tu repositorio en GitHub -> Settings -> Secrets and variables ->
#      Actions -> New repository secret.
#   2. Nombre: ORSAPIKEY   Valor: tu clave real de OpenRouteService.
#   3. Guarda, y haz un nuevo push a main (o relanza el workflow manualmente
#      desde la pestaña Actions) para que el despliegue la recoja.
#
# Es opcional por diseño: si no creas el secreto, el backend sigue
# funcionando exactamente igual que hasta ahora (rutas por línea recta, sin
# geocodificación automática ni planificación con VROOM) -- nunca rompe el
# despliegue.
# ============================================================================

TARGET_DIR="${1:-.}"
cd "$TARGET_DIR"

echo "Aplicando Fase 8e sobre: $(pwd)"
echo

FILES_APPLIED=(
  ".github/workflows/deploy-cloud-run.yml"
)

echo "-> .github/workflows/deploy-cloud-run.yml"
mkdir -p "$(dirname ".github/workflows/deploy-cloud-run.yml")"
base64 -d > ".github/workflows/deploy-cloud-run.yml" <<'B64EOF__github_workflows_deploy_cloud_run_yml'

B64EOF__github_workflows_deploy_cloud_run_yml

echo
echo "Fase 8e aplicada correctamente."
echo "Ficheros actualizados:"
for f in "${FILES_APPLIED[@]}"; do
  echo "  - $f"
done
echo
echo "RECUERDA: crea el secreto de GitHub \"ORSAPIKEY\" (Settings > Secrets and"
echo "variables > Actions) con tu clave real de OpenRouteService, y vuelve a"
echo "desplegar (push a main o \"Re-run jobs\" en Actions) para que se aplique."
